      "path": "package.json",
      "content": "{\n  \"name\": \"hindsight\",\n  \"private\": true,\n  \"workspaces\": [\n    \"hindsight-clients/typescript\",\n    \"hindsight-control-plane\",\n    \"hindsight-docs\",\n    \"hindsight-all-npm\"\n  ],\n  \"scripts\": {\n    \"prepare\": \"./scripts/setup-hooks.sh\"\n  },\n  \"overrides\": {\n    \"qs\": \">=6.16.0 <7.0.0\",\n    \"fast-xml-parser\": \">=5.5.6\",\n    \"serialize-javascript\": \"^7.1.3\",\n    \"minimatch\": \"^3.1.4\",\n    \"undici\": \">=7.30.1 <8.0.0\",\n    \"flatted\": \">=3.4.2\",\n    \"picomatch\": \">=2.3.2 <3.0.0 || >=4.0.4\",\n    \"yaml\": \">=1.10.3\",\n    \"svgo\": \">=4.1.0\",\n    \"dompurify\": \">=3.4.17\",\n    \"@redocly/openapi-core\": {\n      \"minimatch\": \"^5.1.8\"\n    },\n    \"@typescript-eslint/typescript-estree\": {\n      \"minimatch\": \"^9.0.7\"\n    },\n    \"ajv-formats\": {\n      \"ajv\": \"^8.18.0\"\n    },\n    \"handlebars\": \">=4.7.10\",\n    \"path-to-regexp\": \">=0.1.13\",\n    \"brace-expansion\": \">=1.1.18 <2.0.0 || >=2.1.4 <3.0.0\",\n    \"lodash-es\": \">=4.18.1\",\n    \"mermaid\": \">=11.16.1\",\n    \"websocket-driver\": \">=0.7.5\",\n    \"http-proxy-middleware\": \">=2.0.10 <3\",\n    \"next\": \">=16.4.1 <17\",\n    \"fast-uri\": \">=3.1.9 <4\",\n    \"sharp\": \">=0.35.4\",\n    \"shell-quote\": \">=1.9.0\",\n    \"@istanbuljs/load-nyc-config\": {\n      \"js-yaml\": \"^3.15.2\"\n    },\n    \"gray-matter\": {\n      \"js-yaml\": \"^3.15.2\"\n    },\n    \"sockjs\": {\n      \"uuid\": \"^11.1.1\"\n    },\n    \"postcss\": \">=8.5.23\",\n    \"js-yaml\": \">=3.15.2 <4.0.0 || >=4.3.2 <5.0.0\",\n    \"nanoid\": \">=3.3.18 <4.0.0\",\n    \"webpack-dev-server\": \">=5.2.6 <6.0.0\",\n    \"esbuild\": \">=0.28.1 <0.29.0\",\n    \"body-parser\": \">=1.20.9 <2.0.0\",\n    \"browserslist\": \">=4.28.7 <5.0.0\",\n    \"postcss-selector-parser\": \">=7.1.6 <8.0.0\",\n    \"colord\": \">=2.9.4 <3.0.0\",\n    \"joi\": \">=17.13.6 <18.0.0\",\n    \"tinypool\": \">=2.1.2 <3.0.0\",\n    \"katex\": \">=0.18.2 <0.19.0\"\n  }\n}\n"
