    {
      "path": "hindsight-integrations/coding-agents/src/dsh.ts",
      "content": "/**\n * DeepSeek Harness (`dsh`) entrypoint — a native Cordis plugin.\n *\n * dsh is plugin-first: its canonical extension surface is a set of typed lifecycle events, and its\n * Claude Code / Codex hook bridges are just translators onto that same surface. So this integration\n * binds the events directly instead of installing hook binaries — a bridge would cost the same\n * install (neither bridge ships in a default profile) while losing the transcript, the session id\n * and the awaited stop boundary.\n *\n *   agent/session-start  -> RuntimeCore.seedIfCold      (cold-check + background git/codebase seed)\n *   agent/pre-step       -> RuntimeCore.onPrompt        (recall) + the injection as a sourced message\n *   agent/turn-stopping  -> RuntimeCore.onSessionIdle   (write-back of the completed exchange)\n *   ctx.tools            -> the hindsight_* knowledge suite, registered natively\n *\n * ONE dsh PROCESS SERVES MANY WORKSPACES. Unlike opencode/Kilo/Cline — one process, one project —\n * dsh's Web UI creates sessions in whatever directory the user picks, each with its own\n * `session.header.cwd`. Memory is per-repo, so a RuntimeCore (bank, client, seed) is built PER\n * WORKSPACE ROOT and cached, never once per process.\n *\n * The plugin imports NOTHING from dsh at all: every host shape is structurally typed here, and the\n * tool definitions are built in dsh's own registry shape rather than through its `defineTool`\n * builder (see `toDshParameters`). So there is no dsh package for pnpm to resolve inside a profile,\n * and no version to keep in step — any dsh whose event names still match can load this file.\n */\nimport { randomUUID } from \"node:crypto\";\nimport { resolveHostMemory } from \"./core/host-client\";\nimport { diag } from \"./core/diag\";\nimport type { ToolSpec } from \"./core/knowledge-tools\";\nimport { log } from \"./core/log\";\nimport { RuntimeCore } from \"./core/runtime\";\nimport { HINDSIGHT_PLUGIN, readDshEvents, type DshSessionEvent } from \"./core/transcript-dsh\";\n\nconst HARNESS = \"dsh\";\n\n/** Cordis plugin name (loader diagnostics, and the `source.plugin` on everything we inject). */\nexport const name = HINDSIGHT_PLUGIN;\n\n/** The agent registry owns the lifecycle events below; without it there is nothing to bind. */\nexport const inject = [\"agents\"];\n\n// ── host shapes (structural: this package must not depend on dsh's packages) ─────\n\ninterface DshSession {\n  readonly header: { readonly id: string; readonly cwd?: string; readonly origin?: string };\n  /**\n   * Legacy in-memory event log. Present on DeepSeek Harness < alpha.4; removed in alpha.4+.\n   * Prefer {@link snapshotEvents} when available.\n   */\n  readonly events?: readonly DshSessionEvent[];\n  /** Public accessor on DeepSeek Harness alpha.4+ (replaces the removed `events` property). */\n  snapshotEvents?(): readonly DshSessionEvent[];\n  /** How many leading events a FORK copied from its parent (`session/fork`); 0 or absent otherwise.\n   *  Persisted with the session, so it survives a restart. */\n  readonly inheritedEventCount?: number;\n}\n\ninterface DshAgent {\n  readonly session: DshSession;\n}\n\n/** A `user/message` as dsh's pre-step decision carries it. */\ninterface DshUserMessage {\n  role: \"user\";\n  content: { type: string; text?: string }[];\n  source: { kind: string; form?: string };\n  id?: string;\n}\n\ntype PreStepDecision =\n  | { kind: \"enter\"; messages: DshUserMessage[] }\n  | { kind: \"reject\"; [key: string]: unknown };\n\ninterface PreStepPayload {\n  agent: DshAgent;\n  signal: AbortSignal;\n}\n\n/** The Cordis context surface this plugin uses. */\ninterface DshContext {\n  on(\n    event: \"agent/session-start\",\n    listener: (payload: { agent: DshAgent }) => void\n  ): (() => void) | void;\n  on(\n    event: \"agent/pre-step\",\n    listener: (\n      payload: PreStepPayload,\n      next: () => Promise<PreStepDecision>\n    ) => Promise<PreStepDecision>,\n    options?: { prepend?: boolean }\n  ): (() => void) | void;\n  on(\n    event: \"agent/turn-stopping\",\n    listener: (payload: { agent: DshAgent }) => Promise<void> | void\n  ): (() => void) | void;\n  on(\n    event: \"agent/disposed\",\n    listener: (payload: { agent: DshAgent }) => void\n  ): (() => void) | void;\n  inject(names: string[], callback: (ctx: DshToolContext) => void): void;\n}\n\ninterface DshToolContext {\n  tools: {\n    register(definition: unknown): void;\n    /** Registry introspection; used only to log what the host ended up exposing. */\n    schemas?(): { name: string }[];\n  };\n}\n\n/** `exec` as a dsh tool body receives it (only the caller matters to us). */\ninterface DshToolRunContext {\n  readonly agent?: DshAgent;\n}\n\n// ── per-workspace runtime cache ─────────────────────────────────────────────────\n\nexport interface Workspace {\n  core: RuntimeCore;\n  root: string;\n  /** Started by the first SESSION in this repo, then shared by every later one. */\n  seeded?: Promise<void>;\n  tools?: ToolSpec[];\n}\n\n/** `null` caches \"memory is off for this repo\" so a disabled bank isn't re-derived every turn. */\nconst workspaces = new Map<string, Workspace | null>();\n/**\n * sessionId -> agent, so a core's transcript source (which only receives the id) can read the live\n * log back on stop. `agent/disposed` is what bounds it: an agent holds its whole session log, so\n * dropping the entry when the host disposes the agent is what keeps a long-lived Web server from\n * pinning every session it ever opened.\n */\nconst liveAgents = new Map<string, DshAgent>();\n\n/**\n * Prefer `session.snapshotEvents()` (DeepSeek Harness alpha.4+); fall back to the legacy\n * `session.events` property so older hosts keep working. Missing both yields an empty log —\n * which is exactly the alpha.4 breakage when callers still read `events` alone.\n */\nexport function dshSessionEvents(\n  session: Pick<DshSession, \"snapshotEvents\" | \"events\">\n): readonly DshSessionEvent[] {\n  return session.snapshotEvents?.() ?? session.events ?? [];\n}\n\n/**\n * The events this session produced itself — what its write-back saves. A fork saves only its new\n * turns (#5940): the prefix it inherited is the parent's conversation, which the parent already\n * stores, and the child's first write-back used to send all of it again under its own document,\n * re-extracting history the bank already held. The full log is still what the model sees, so\n * everything else (the injection dedupe below) reads `dshSessionEvents`.\n */\nexport function ownEvents(\n  session: Pick<DshSession, \"snapshotEvents\" | \"events\" | \"inheritedEventCount\">\n): readonly DshSessionEvent[] {\n  return dshSessionEvents(session).slice(session.inheritedEventCount ?? 0);\n}\n\n/** Where a session is working. dsh records it on the session header; a session without one is rare. */\nfunction workspaceRoot(agent: DshAgent): string {\n  return agent.session.header.cwd || process.cwd();\n}\n\n/**\n * The memory runtime for one workspace root, built on first use.\n *\n * Bank derivation and the per-bank opt-out live here rather than in `apply`, because the plugin\n * loads before any session exists and the process may end up serving several unrelated\n * repositories. Building one has NO side effect: the seed is started by `ensureSeeded` when a\n * session actually opens, so merely registering the tools never seeds the launch directory.\n */\nfunction workspaceFor(root: string): Workspace | undefined {\n  const cached = workspaces.get(root);\n  if (cached !== undefined) return cached ?? undefined;\n\n  // One shared builder for every long-lived host (core/host-client.ts): the global switch, the\n  // per-bank opt-out and `optInOnly` all land in `cfg.disabled`.\n  const { cfg, bankId, client } = resolveHostMemory(HARNESS, root);\n  if (cfg.disabled) {\n    workspaces.set(root, null); // inert: same agent, no memory (baseline parity)\n    return undefined;\n  }\n  // The 5th argument is this host's whole reason for existing here: RuntimeCore binds the\n  // knowledge tools (and retain stamps) to the workspace it is given, and dsh's process cwd is the\n  // launch directory, routinely a different repository from the session's.\n  const core = new RuntimeCore(client, bankId, cfg, HARNESS, root);\n  // The write-back path reads the log back off the live agent — dsh keeps the whole session in\n  // memory, so unlike opencode there is nothing to refetch over HTTP.\n  core.setTranscriptSource(async (sessionId) => {\n    const agent = liveAgents.get(sessionId);\n    return agent ? readDshEvents(ownEvents(agent.session)) : [];\n  });\n  const workspace: Workspace = { core, root };\n  workspaces.set(root, workspace);\n  return workspace;\n}\n\n/**\n * Start this repo's cold-check + background seed once.\n *\n * Fire-and-forget by design: `agent/session-start` is an emit that no extension point awaits, and\n * the Web UI must not wait on a network round-trip to open a session. Nothing the first prompt\n * needs comes from here — it builds its own knowledge preamble from that session's page list.\n */\nfunction ensureSeeded(workspace: Workspace): void {\n  workspace.seeded ??= workspace.core.seedIfCold(workspace.root);\n}\n\nfunction workspaceForAgent(agent: DshAgent): Workspace | undefined {\n  // A subagent session is a child of a conversation we already track: injecting into it would pay\n  // for a second recall per delegation, and retaining it would file a fragment of a session that\n  // the parent already stores in full.\n  if (agent.session.header.origin === \"subagent\") return undefined;\n  return workspaceFor(workspaceRoot(agent));\n}\n\n// ── message helpers ─────────────────────────────────────────────────────────────\n\n/**\n * The human text in this step's claimed batch.\n *\n * `agent/pre-step` fires before EVERY step, including tool continuations that claimed no new input,\n * and other plugins contribute their own context messages to the same batch (V3 hosts tag them\n * `kind: 'plugin'`, V4 hosts use a producer-owned kind such as `time-context`). Only a\n * `kind: 'user'` message is a prompt worth recalling on.\n */\nfunction promptOf(messages: readonly DshUserMessage[]): string {\n  return (messages || [])\n    .filter((message) => message?.source?.kind === \"user\")\n    .flatMap((message) => message.content || [])\n    .filter((block) => block?.type === \"text\" && block.text)\n    .map((block) => block.text!)\n    .join(\"\\n\")\n    .trim();\n}\n\n/**\n * Build the injected memory message.\n *\n * `form: 'recall'` is dsh's own vocabulary for retrieved context, so its UI renders the block as\n * recalled material rather than as something the user typed. Session format V4 requires injected\n * messages to use a producer-owned source kind; `plugin:hindsight` is the canonical fallback name\n * for an unregistered plugin. The non-user source also keeps the block out of a write-back.\n */\nfunction injectionMessage(text: string): DshUserMessage {\n  return {\n    id: randomUUID(),\n    role: \"user\",\n    content: [{ type: \"text\", text }],\n    source: { kind: `plugin:${HINDSIGHT_PLUGIN}`, form: \"recall\" },\n  };\n}\n\n/**\n * The text of the last memory block this session's history carries, if any.\n *\n * dsh keeps every injected message in the history it sends, so re-appending an unchanged block (the\n * per-turn roster) only stacks identical copies (#5026). This used to be remembered in a map keyed\n * by session id, which a fork (new id, inherited history) and a restart (empty map) both reset while\n * the block was still in the history — so the next unchanged recall appended a second copy (#5940).\n * Reading it off the history itself is what the model will actually see.\n */\nexport function lastInjectedText(events: readonly DshSessionEvent[]): string | undefined {\n  for (let i = events.length - 1; i >= 0; i--) {\n    const event = events[i];\n    if (event?.type !== \"user/message\") continue;\n    const message = event.data as Partial<DshUserMessage> | undefined;\n    if (message?.source?.kind !== `plugin:${HINDSIGHT_PLUGIN}`) continue;\n    return (message.content ?? []).map((block) => block.text ?? \"\").join(\"\\n\");\n  }\n  return undefined;\n}\n\n// ── the lifecycle, testable without a dsh host ──────────────────────────────────\n\n/**\n * The three lifecycle handlers, over an injectable workspace resolver. `apply` binds these to the\n * real Cordis events; the tests drive them with a stand-in agent and core.\n */\nexport function createDshHooks(resolve: (agent: DshAgent) => Workspace | undefined) {\n  return {\n    sessionStart({ agent }: { agent: DshAgent }): void {\n      const workspace = resolve(agent);\n      if (!workspace) return;\n      liveAgents.set(agent.session.header.id, agent);\n      ensureSeeded(workspace);\n    },\n\n    async preStep(\n      { agent, signal }: PreStepPayload,\n      next: () => Promise<PreStepDecision>\n    ): Promise<PreStepDecision> {\n      const decision = await next();\n      if (decision.kind !== \"enter\" || signal.aborted) return decision;\n      const workspace = resolve(agent);\n      if (!workspace) return decision;\n      const sessionId = agent.session.header.id;\n      liveAgents.set(sessionId, agent);\n      // A resumed session gets no `agent/session-start` in some compositions; seeding here too\n      // keeps the cold-check exactly-once without depending on which events a host fired.\n      ensureSeeded(workspace);\n      // No new human input means a tool continuation: recall already ran for this turn, and its\n      // block is already in the history the model is about to be sent.\n      const prompt = promptOf(decision.messages);\n      if (!prompt) return decision;\n      await workspace.core.onPrompt(sessionId, prompt);\n      const injection = workspace.core.getInjection(sessionId);\n      if (!injection) {\n        diag(HARNESS, \"inject_empty\", { session: sessionId });\n        return decision;\n      }\n      if (injection === lastInjectedText(dshSessionEvents(agent.session))) {\n        diag(HARNESS, \"inject_unchanged\", { session: sessionId });\n        return decision;\n      }\n      diag(HARNESS, \"inject_ok\", { session: sessionId, chars: injection.length });\n      return { kind: \"enter\", messages: [...decision.messages, injectionMessage(injection)] };\n    },\n\n    async turnStopping({ agent }: { agent: DshAgent }): Promise<void> {\n      const workspace = resolve(agent);\n      if (!workspace) return;\n      const sessionId = agent.session.header.id;\n      liveAgents.set(sessionId, agent);\n      // The stop boundary is the only moment the completed exchange is readable, so this bypasses\n      // the turn cadence exactly like the opencode idle path it shares (`onSessionIdle`).\n      await workspace.core.onSessionIdle(sessionId);\n    },\n\n    disposed({ agent }: { agent: DshAgent }): void {\n      liveAgents.delete(agent.session.header.id);\n    },\n  };\n}\n\n// ── native tools ────────────────────────────────────────────────────────────────\n\n/**\n * Project one harness-agnostic ToolSpec's input onto the JSON Schema dsh's registry stores.\n *\n * dsh's own `defineTool` is a pure builder — it compiles this exact schema shape and wraps the\n * callbacks — and `ctx.tools.register` validates a definition structurally, not by module identity.\n * Building the schema here therefore keeps the plugin free of a `@deepseek-ai/dsh-tools` dependency\n * that pnpm would have to resolve inside the profile, at the cost of one small projection.\n *\n * Our specs state their input as a Zod raw shape (the MCP dialect every harness shares) and are\n * deliberately flat: required or optional strings. Optionality and the description are the only two\n * facts to carry across; a parameter that is ever anything but a string fails loudly here rather\n * than registering a mis-typed tool.\n */\nexport function toDshParameters(spec: ToolSpec): Record<string, unknown> {\n  const properties: Record<string, unknown> = {};\n  const required: string[] = [];\n  for (const [key, schema] of Object.entries(spec.inputSchema)) {\n    const zod = schema as {\n      def?: { type?: string; innerType?: { def?: { type?: string } } };\n      description?: string;\n      isOptional?: () => boolean;\n    };\n    // `.optional()` wraps the real type, so unwrap before checking it — otherwise every optional\n    // parameter would pass the guard below whatever it actually holds.\n    const inner = zod.def?.type === \"optional\" ? zod.def.innerType?.def?.type : zod.def?.type;\n    if (inner !== undefined && inner !== \"string\") {\n      throw new Error(\n        `hindsight tool ${spec.name}: dsh projection supports string parameters only`\n      );\n    }\n    properties[key] = {\n      type: \"string\",\n      ...(zod.description ? { description: zod.description } : {}),\n    };\n    if (typeof zod.isOptional !== \"function\" || !zod.isOptional()) required.push(key);\n  }\n  return { type: \"object\", properties, ...(required.length ? { required } : {}) };\n}\n\n/** The tool bodies return MCP-shaped results and never throw; dsh wants a value or a throw. */\nasync function runSpec(spec: ToolSpec, args: Record<string, unknown>): Promise<string> {\n  const result = await spec.handler(args);\n  const text = (result.content || []).map((block) => block.text).join(\"\\n\");\n  // dsh normalizes a thrown tool body into an isError result with this message, which is exactly\n  // what our isError:true means — mapping it any other way would report a failure as a success.\n  if (result.isError) throw new Error(text || \"hindsight tool failed\");\n  return text;\n}\n\n/**\n * Register the hindsight_* suite on `ctx.tools`.\n *\n * The dsh tools registry is host+per-scope layered, so a host-plane registration is visible to\n * every agent — including the Web surface's per-session agent presets. Each call resolves the bank\n * from the CALLING agent's workspace, because one process serves many repositories.\n */\nfunction registerTools(toolCtx: DshToolContext, fallbackRoot: string): void {\n  // The registry is populated at plugin load, before any session exists, so the NAMES and schemas\n  // come from the launch directory's workspace and each call rebinds to its own caller's bank. The\n  // one consequence: if memory is off for the launch directory specifically (a `banks.<id>`\n  // opt-out) the tools are absent even for other repositories this process later serves.\n  const template = workspaceFor(fallbackRoot);\n  if (!template) return; // memory disabled where this process was launched\n  for (const spec of specsOf(template)) {\n    toolCtx.tools.register({\n      name: spec.name,\n      description: spec.description,\n      parameters: toDshParameters(spec),\n      output: {\n        schema: { type: \"string\" },\n        render: (_args: unknown, value: string) => [{ type: \"text\", text: value }],\n      },\n      async execute(args: Record<string, unknown>, exec: DshToolRunContext): Promise<string> {\n        // Bind to the caller's repository, not to whichever workspace happened to load first.\n        const workspace = exec?.agent ? workspaceForAgent(exec.agent) : template;\n        if (!workspace) return \"Hindsight memory is disabled for this workspace.\";\n        const bound = specsOf(workspace).find((candidate) => candidate.name === spec.name);\n        if (!bound) return `Hindsight tool ${spec.name} is unavailable.`;\n        return runSpec(bound, args);\n      },\n    });\n  }\n  // Log what the HOST sees, not just what we handed it: a tool that registers cleanly but never\n  // reaches a model is the failure mode worth catching, and this is the one line that shows it.\n  const exposed = toolCtx.tools.schemas?.() ?? [];\n  log.debug(HARNESS, \"tools registered\", {\n    count: specsOf(template).length,\n    hostCatalog: exposed.length,\n    hindsight: exposed.filter((schema) => schema.name?.startsWith(\"hindsight_\")).length,\n  });\n}\n\n/** The tool specs for one workspace, built once (each closes over that bank's client and root). */\nfunction specsOf(workspace: Workspace): ToolSpec[] {\n  workspace.tools ??= workspace.core.toolSpecs();\n  return workspace.tools;\n}\n\n// ── cordis entrypoint ───────────────────────────────────────────────────────────\n\n/**\n * Bind the memory lifecycle for the lifetime of `ctx`. Every listener is fail-open: RuntimeCore\n * never throws, and a workspace we cannot resolve simply leaves that session unmemoried.\n */\nexport function apply(ctx: DshContext): void {\n  const hooks = createDshHooks(workspaceForAgent);\n  ctx.on(\"agent/session-start\", hooks.sessionStart);\n  // `prepend: true` puts this listener outermost, so the injection is appended AFTER every other\n  // contributor's messages — the memory block reads last, closest to the model's turn.\n  ctx.on(\"agent/pre-step\", hooks.preStep, { prepend: true });\n  ctx.on(\"agent/turn-stopping\", hooks.turnStopping);\n  ctx.on(\"agent/disposed\", hooks.disposed);\n  // The tools registry is optional: a composition without it (a bare headless assembly) still gets\n  // recall, injection and write-back.\n  ctx.inject([\"tools\"], (toolCtx) => {\n    registerTools(toolCtx, process.cwd());\n  });\n}\n\nexport default { name, inject, apply };\n"
    },
    {
      "path": "hindsight-integrations/coding-agents/src/core/runtime.ts",
      "content": "/**\n * Host adapter runtime for PERSISTENT-PLUGIN harnesses (opencode, opencode2, Kilo, Cline, dsh, pi,\n * Prime Agent — every host that loads us once and keeps us). It delegates SessionStart and\n * prompt behavior to the same core lifecycle as fresh-process hook harnesses; this class keeps only\n * the host-specific injection, toast, and incremental-transcript responsibilities.\n *\n * A harness adapter feeds it three normalized events and reads two values back:\n *   - seedIfCold(repoPath)          : plugin load -> cold-check auto-seed (the page preamble is\n *                                     NOT computed here; onPrompt builds it per session)\n *   - onPrompt(sessionId, prompt)   : each user turn -> recall + build this turn's injection\n *   - getInjection(sessionId)       : the text to inject into this turn's user message (or undefined)\n *   - toolSpecs()                   : the hindsight_* knowledge/recall tools to register natively\n *   - onTranscript(sessionId, turns, lastTurnComplete): full transcript -> write back (on by default)\n *   - onSessionIdle(sessionId)      : assistant finished -> refetch + write back the completed\n *                                     exchange (the Stop-equivalent these hosts lack)\n *   - flush()                       : host is exiting -> wait (bounded) for in-flight write-backs\n * No opencode/claude specifics live here — only the memory logic.\n */\nimport type { Config } from \"./config\";\nimport { maybeAutoUpdate } from \"./auto-update\";\nimport { DAEMON_WAIT_RETAIN_MS, DAEMON_WAIT_SESSION_START_MS, ensureDaemon } from \"./daemon\";\nimport { diag } from \"./diag\";\nimport { describeError, log, setLogLevel } from \"./log\";\nimport type { HindsightClient } from \"./hindsight\";\nimport { buildKnowledgePreamble } from \"./knowledge-injection\";\nimport { buildKnowledgeTools, type ToolSpec } from \"./knowledge-tools\";\nimport { buildPageTrigger } from \"./missions\";\nimport { retainLiveSession, type TransportTurn } from \"./chat\";\nimport { memoryCursorStore } from \"./retain-cursor\";\nimport { memoryUsageCursorStore, recordUsage } from \"./usage\";\nimport { buildRetainStamp } from \"./retain-stamp\";\nimport { buildSessionStartContext } from \"./session-start\";\nimport { syncCompanionSkill } from \"./skill-sync\";\nimport { buildHookOutput } from \"./hook\";\nimport { sessionCacheFile, writeSessionCache } from \"./session-cache\";\n\nconst HARNESS = \"opencode\";\n/** How long `flush` holds a host's exit for in-flight write-backs: room for one retain request. */\nconst FLUSH_TIMEOUT_MS = 10_000;\n\nexport class RuntimeCore {\n  private readonly injection = new Map<string, string>(); // sessionId -> this turn's injection block\n  private readonly turnCount = new Map<string, number>(); // sessionId -> user-turn counter (cadence)\n  private readonly sessionState = new Map<string, { startTs: string; retainedTurns: number }>();\n  /** Live write-back cursors. In memory, unlike the hook harnesses': this host outlives the session. */\n  private readonly cursors = memoryCursorStore();\n  /** Turns already written to the usage log (core/usage.ts), per session. */\n  private readonly usageCursors = memoryUsageCursorStore();\n  /** Pulls a session's CURRENT transcript from the host (set by the adapter); see onSessionIdle. */\n  private fetchTranscript?: (sessionId: string) => Promise<TransportTurn[]>;\n  /** Write-backs started and not yet settled — what `flush` waits for. */\n  private readonly inFlight = new Set<Promise<void>>();\n  private deferInitialReflect = false;\n  /** Host-notice channel (opencode/Kilo: client.tui.showToast via the adapter). Optional, fail-open. */\n  private notify?: (title: string, message: string) => void;\n\n  constructor(\n    private readonly client: HindsightClient,\n    private readonly bankId: string,\n    private readonly cfg: Config,\n    /**\n     * Which persistent-plugin host loaded us. Scopes diagnostics, the session cache file and the\n     * retained transcript's harness field, so Kilo sessions don't masquerade as opencode ones.\n     * Defaults to opencode, the original (and only other) plugin harness.\n     */\n    readonly harness: string = HARNESS,\n    /** Workspace root this host opened — the SAME directory bank resolution used, so a\n     *  `{gitProject}` in retainTags names the repo the bank was derived from. */\n    private readonly projectDir: string = process.cwd()\n  ) {\n    setLogLevel(cfg.logLevel);\n  }\n\n  setNotifier(notify: (title: string, message: string) => void): void {\n    this.notify = notify;\n  }\n\n  /**\n   * Supply a way to READ the session's transcript back from the host. Without it `onSessionIdle`\n   * no-ops, so hosts that can't refetch keep the old (lagging) turn-driven write-back rather than\n   * retaining a stale transcript.\n   */\n  setTranscriptSource(fetch: (sessionId: string) => Promise<TransportTurn[]>): void {\n    this.fetchTranscript = fetch;\n  }\n\n  /** The hindsight_* knowledge + recall tools, bound to this bank, for the harness to register natively. */\n  toolSpecs(): ToolSpec[] {\n    return buildKnowledgeTools(this.client, this.bankId, {\n      repoDir: this.projectDir,\n      harness: this.harness,\n      pageTrigger: buildPageTrigger(this.cfg),\n      reflectTimeoutMs: this.cfg.reflectToolTimeoutMs,\n      reflectBudget: this.cfg.reflectBudget,\n      toolGuideExtra: this.cfg.toolGuideExtra,\n      stampFor: () =>\n        buildRetainStamp(this.cfg, {\n          directory: this.projectDir,\n          harness: this.harness,\n          bankId: this.bankId,\n        }),\n    });\n  }\n\n  get writeBackEnabled(): boolean {\n    return this.cfg.retainSessions;\n  }\n\n  /**\n   * Plugin load (SessionStart-equivalent): on a cold repo, deterministically start the background\n   * git-log seed + codebase survey. Reuses the exact hook-harness logic\n   * (`buildSessionStartContext`) so opencode seeds identically. Never throws.\n   *\n   * It deliberately does NOT keep that call's knowledge preamble. This runs once per PROCESS and\n   * these hosts outlive every session, so a roster captured here is stale for every session but\n   * the first — `onPrompt` builds its own from the session's live page list (#4607).\n   */\n  async seedIfCold(repoPath: string | undefined): Promise<void> {\n    // Anti-recursion: a headless survey session runs the agent (which loads this plugin) with\n    // HINDSIGHT_DISABLE_HOOKS=1 — the tools stay registered (toolSpecs, so the survey can ingest),\n    // but seeding/recall/write-back must no-op or the survey would re-seed itself (see core/survey.ts).\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return;\n    // Companion skill, the same housekeeping `runSessionStartHook` does for hook harnesses — but\n    // with `install`, because a persistent-plugin host can be wired by its OWN plugin manager\n    // (`dsh plugin add …`, `cline plugin install`), a route our installer never sees, leaving the\n    // plugin loaded with its tools registered and no skill on disk at all (#4406). No-op for a host\n    // with no skills directory (opencode; opencode2 registers it in memory instead).\n    syncCompanionSkill(this.harness, { install: true });\n    // Daemon mode: this is the SessionStart of a persistent-plugin host, so it owns the same\n    // warm-up the hook harnesses do in `runSessionStartHook` — start it before the user has typed\n    // anything, wait only briefly, and let a cold one keep coming up in the background. Without it\n    // these hosts never started a daemon at all and every request failed with ECONNREFUSED (#3524);\n    // `runSessionStartHook` is a hook-only wrapper, so calling `buildSessionStartContext` directly\n    // (as every plugin harness does) skipped the ensure entirely.\n    await ensureDaemon(this.cfg, this.harness, { waitMs: DAEMON_WAIT_SESSION_START_MS });\n    // Same session-start housekeeping the hook harnesses do in `runSessionStartHook`: a persistent\n    // plugin host is a session start too, and leaving it out would mean opencode/Kilo/Cline users\n    // never got an update — the parity gap `ensureDaemon` above already had to be fixed for.\n    void maybeAutoUpdate(this.cfg);\n    try {\n      const out = await buildSessionStartContext({\n        cwd: repoPath || process.cwd(),\n        bankId: this.bankId,\n        cfg: this.cfg,\n        client: this.client,\n        harness: this.harness,\n      });\n      // The seed note is user-facing; opencode has no visible-system channel at load, so surface it\n      // on stderr (shows in the plugin log / console) rather than dropping it.\n      // Banner: via the host's toast API when available (stderr corrupts the TUI); always logged.\n      if (out.systemMessage) {\n        const plain = out.systemMessage.replace(/\\x1b\\[[0-9;]*m/g, \"\");\n        log.info(this.harness, plain);\n        this.notify?.(\"Hindsight\", plain.replace(/^Hindsight is /, \"Is \"));\n      }\n      this.deferInitialReflect = out.deferInitialReflect === true;\n    } catch {\n      /* seeding is best-effort — a cold-check failure never breaks the agent */\n    }\n  }\n\n  /**\n   * Each user turn delegates to the same `buildHookOutput` used by hook harnesses. The cache file\n   * intentionally replaces the old in-memory reflect/page state, keeping lifecycle behavior\n   * identical across hosts while this adapter retains only delivery-specific state.\n   */\n  async onPrompt(sessionId: string | undefined, prompt: string): Promise<void> {\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return; // anti-recursion (see seedIfCold)\n    if (!sessionId) return;\n    // No prompt text means no recall, so no block for this turn either: the previous turn's block\n    // must not be handed out again, since every host now persists it into the user message.\n    if (!prompt.trim()) {\n      this.injection.delete(sessionId);\n      return;\n    }\n    const turns = (this.turnCount.get(sessionId) ?? 0) + 1;\n    this.turnCount.set(sessionId, turns);\n\n    const cacheFile = sessionCacheFile(this.harness, sessionId);\n    if (this.deferInitialReflect) {\n      // `seedIfCold` has no session id. Transfer its SessionStart decision to the first concrete\n      // session here; `buildHookOutput` consumes it exactly once, like hook harnesses do.\n      this.deferInitialReflect = false;\n      writeSessionCache(cacheFile, { deferInitialReflect: true });\n    }\n    const output = await buildHookOutput({\n      harness: this.harness,\n      prompt,\n      cfg: this.cfg,\n      client: this.client,\n      cacheFile,\n    });\n\n    const blocks: string[] = [];\n    // The SessionStart-equivalent preamble, injected once on the first turn (later turns get the\n    // periodic refresh below). Built HERE, from this session's own roster, rather than reused from\n    // plugin load: that one is a process-lifetime snapshot, so a host started before the pages\n    // existed told every later session \"No knowledge pages yet\" while the same turn's memory block\n    // listed pages by id (#4607).\n    if (turns === 1) {\n      blocks.push(\n        buildKnowledgePreamble(output.pages, {\n          reflectOnNewGoals: this.cfg.autoInject !== \"reflect\",\n          extra: this.cfg.toolGuideExtra,\n        })\n      );\n    }\n    if (output.context) blocks.push(output.context);\n    // OpenCode has no user-message hook channel; use its native toast instead of stderr, which\n    // renders inside the TUI input line. The shared output owns when a notice exists.\n    if (output.notice) {\n      const preview = output.notice.replace(/\\s+/g, \" \").trim().slice(0, 140);\n      log.info(this.harness, \"reflect goal\", { preview });\n      this.notify?.(\"Hindsight · recalled past decisions\", preview);\n    }\n    const block = blocks.filter(Boolean).join(\"\\n\\n\");\n    this.injection.set(sessionId, block);\n  }\n\n  /**\n   * The text to inject into this turn's user message (built by the preceding onPrompt), or\n   * undefined.\n   *\n   * It goes into the USER turn on every host, never the system prompt (#5914). The block changes\n   * from turn to turn — the recall runs once, the roster refresh on a cadence — so a system prompt\n   * carrying it differed between requests and broke the provider's prefix cache from that point\n   * on. Persisted in the turn it belongs to, it leaves the system prompt and the earlier history\n   * byte-identical. That used to need a fallback to the most recent block for opencode's\n   * `experimental.chat.system.transform`, which fired with no session id; nothing reads it that\n   * way any more.\n   */\n  getInjection(sessionId: string): string | undefined {\n    return this.injection.get(sessionId) || undefined;\n  }\n\n  /**\n   * Full normalized transcript (rich: user/assistant text + tool calls/outputs): upsert every turn\n   * when enabled. On by default for persistent-plugin hosts (parity with hook-harness Stop\n   * write-back), so opencode sessions compound into memory; opt out with `retainSessions: false`.\n   *\n   * There is deliberately no client-side cadence. Batching write-backs meant holding turns in a\n   * process the host can close at any moment, with no reliable signal on the way out — the flush a\n   * cadence needs would have to ride a session-end hook, and those are cancelled at shutdown. The\n   * server coalesces instead: queued retains for one document fold into a single execution\n   * (`engine.retain.fold`), so submitting every turn costs one extraction, not one per turn, and\n   * nothing is ever held somewhere it can be lost.\n   */\n  async onTranscript(\n    sessionId: string,\n    turns: TransportTurn[],\n    /** Whether the agent has finished answering the last prompt. Required, not defaulted: opencode\n     *  hands this over while BUILDING a request (false), pi and Cline after the run ends (true), and\n     *  a wrong default records every turn one late and never the session's last. */\n    lastTurnComplete: boolean\n  ): Promise<void> {\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return; // anti-recursion (see seedIfCold)\n    if (!sessionId || !turns.length) return;\n    // Usage is a local file, so it is recorded whether or not write-back is on (#5391).\n    this.recordUsage(sessionId, turns, lastTurnComplete);\n    if (!this.writeBackEnabled) return;\n    const st = this.stateFor(sessionId);\n    this.retain(sessionId, turns, st.startTs);\n  }\n\n  /**\n   * Session went idle — the assistant has finished replying.\n   *\n   * This is the Stop-equivalent these hosts lack. `onTranscript` alone is driven by\n   * `messages.transform`, which the host runs while BUILDING a request, so the transcript it hands\n   * us never contains the reply that request produced: write-back always lagged one user turn, and\n   * a session's final exchange was never retained at all. Refetching here (rather than replaying a\n   * cached list) is the whole point — the cached one predates the reply.\n   *\n   * Cadence is deliberately bypassed: idle means \"there may be nothing after this\", so a pending\n   * turn must not wait for a threshold it will never reach.\n   */\n  async onSessionIdle(sessionId: string): Promise<void> {\n    if (process.env.HINDSIGHT_DISABLE_HOOKS) return; // anti-recursion (see seedIfCold)\n    if (!sessionId || !this.fetchTranscript) return;\n    let turns: TransportTurn[];\n    try {\n      turns = await this.fetchTranscript(sessionId);\n    } catch (e) {\n      diag(this.harness, \"idle_fetch_failed\", {\n        error: describeError(e),\n        session: sessionId,\n      });\n      return;\n    }\n    if (!turns.length) return;\n    this.recordUsage(sessionId, turns, true); // idle: the reply is in\n    if (!this.writeBackEnabled) return; // usage above is local and recorded regardless (#5391)\n    const st = this.stateFor(sessionId);\n    // idle can fire more than once for one exchange (and again on a session with no new activity);\n    // only retain when this transcript actually grew past what we last wrote.\n    if (turns.length <= st.retainedTurns) return;\n    st.retainedTurns = turns.length;\n    this.retain(sessionId, turns, st.startTs, \"idle\");\n  }\n\n  private recordUsage(sessionId: string, turns: TransportTurn[], lastTurnComplete: boolean): void {\n    recordUsage({\n      harness: this.harness,\n      sessionId,\n      bankId: this.bankId,\n      turns,\n      cursors: this.usageCursors,\n      lastTurnComplete,\n      // No `reviseLastTurn` here, unlike the hook path: this runtime never records a turn before its\n      // reply exists. `onTranscript` is handed `false` while the host is still building the request,\n      // which holds the turn back, and `onSessionIdle` refetches a transcript that includes the\n      // reply before recording it.\n    });\n  }\n\n  private stateFor(sessionId: string): {\n    startTs: string;\n    retainedTurns: number;\n  } {\n    let st = this.sessionState.get(sessionId);\n    if (!st) {\n      st = { startTs: new Date().toISOString(), retainedTurns: 0 };\n      this.sessionState.set(sessionId, st);\n    }\n    return st;\n  }\n\n  /**\n   * Wait for every write-back still in flight, at most `timeoutMs`. Write-backs stay fire-and-forget\n   * so a turn never blocks on the network; a host that announces its exit (pi's `session_shutdown`)\n   * calls this so the session's final retain is not dropped with the process (#5081). Bounded so a\n   * stalled server cannot hold the host's exit open. Never throws.\n   */\n  async flush(timeoutMs = FLUSH_TIMEOUT_MS): Promise<void> {\n    if (!this.inFlight.size) return;\n    let timer: ReturnType<typeof setTimeout> | undefined;\n    await Promise.race([\n      Promise.all(this.inFlight),\n      new Promise<void>((r) => {\n        timer = setTimeout(r, timeoutMs);\n      }),\n    ]);\n    clearTimeout(timer);\n  }\n\n  /** Fire-and-forget upsert of the session transcript; never throws into the host. */\n  private retain(\n    sessionId: string,\n    turns: TransportTurn[],\n    startTs: string,\n    trigger = \"turn\"\n  ): void {\n    const t0 = Date.now();\n    // Daemon mode: the write path is the last chance to get a daemon up — the Stop-hook role, for\n    // hosts that have no Stop hook. A daemon that died mid-session would otherwise take the whole\n    // exchange with it. The wait sits INSIDE the fire-and-forget chain, so\n    // unlike the Stop hook it costs the host nothing: this call already returns before the retain\n    // does. Deliberately not gated on the result — retain proceeds either way, so an unreachable\n    // daemon produces the same `retain_failed` diagnostic as an unreachable Cloud server.\n    const write = ensureDaemon(this.cfg, this.harness, { waitMs: DAEMON_WAIT_RETAIN_MS })\n      .then(() =>\n        retainLiveSession(this.client, sessionId, turns, startTs, this.harness, {\n          cursors: this.cursors,\n          stamp: buildRetainStamp(this.cfg, {\n            directory: this.projectDir,\n            harness: this.harness,\n            bankId: this.bankId,\n            sessionId,\n          }),\n        })\n      )\n      .then(() =>\n        diag(this.harness, \"retain_ok\", {\n          ms: Date.now() - t0,\n          turns: turns.length,\n          session: sessionId,\n          trigger,\n        })\n      )\n      .catch((e) =>\n        diag(this.harness, \"retain_failed\", {\n          ms: Date.now() - t0,\n          error: describeError(e),\n          session: sessionId,\n          trigger,\n        })\n      );\n    this.inFlight.add(write);\n    void write.finally(() => this.inFlight.delete(write));\n  }\n}\n"
    }
  ],
